+  top: 0.5rem;
+}
+
+/* Header */
+.site-header {
+  background: var(--surface);
+  border-bottom: 1px solid var(--border);
+}
+.site-header .container {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 1rem;
+  padding-top: 1rem;
+  padding-bottom: 1rem;
+  max-width: 960px;
+}
+.brand {
+  font-weight: 700;
+  font-size: 1.125rem;
+  color: var(--text);
+  text-decoration: none;
+  letter-spacing: -0.01em;
+}
+.site-header nav ul {
+  display: flex;
+  gap: 1.25rem;
+  list-style: none;
+  margin: 0;
+  padding: 0;
+  flex-wrap: wrap;
+}
+.site-header nav a {
+  color: var(--muted);
+  text-decoration: none;
+  font-weight: 500;
+  padding: 0.25rem 0;
+}
+.site-header nav a:hover {
+  color: var(--text);
+}
+.site-header nav a[aria-current="page"] {
+  color: var(--text);
+  border-bottom: 2px solid var(--accent);
+}
+
+/* Card */
+main {
+  padding: 2.5rem 1.25rem 4rem;
+}
+.card {
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  box-shadow: var(--shadow);
+  padding: 2rem;
+}
+.card-intro {
+  margin-bottom: 1.75rem;
+}
+.eyebrow {
+  margin: 0 0 0.5rem;
+  font-size: 0.8125rem;
+  font-weight: 600;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  color: var(--accent);
+}
+h1 {
+  margin: 0 0 0.5rem;
+  font-size: 1.75rem;
+  letter-spacing: -0.02em;
+  line-height: 1.2;
+}
+.lede {
+  margin: 0 0 1rem;
+  color: var(--muted);
+}
+.required-legend {
+  margin: 0;
+  font-size: 0.875rem;
+  color: var(--muted);
+}
+.required-legend span {
+  color: var(--error);
+  font-weight: 700;
+}
+
+/* Form */
+.contact-form {
+  display: flex;
+  flex-direction: column;
+  gap: 1.25rem;
+}
+.form-field {
+  display: flex;
+  flex-direction: column;
+  gap: 0.375rem;
+}
+.form-field label {
+  font-weight: 600;
+  font-size: 0.9375rem;
+}
+.req {
+  color: var(--error);
+  margin-left: 2px;
+}
+.optional {
+  font-weight: 400;
+  color: var(--muted);
+  font-size: 0.875rem;
+  margin-left: 0.25rem;
+}
+
+.form-field input {
+  font: inherit;
+  color: var(--text);
+  background: var(--surface);
+  border: 1px solid var(--border-strong);
+  border-radius: 8px;
+  padding: 0.625rem 0.75rem;
+  width: 100%;
+  transition: border-color 0.15s ease, box-shadow 0.15s ease;
+}
+.form-field input::placeholder {
+  color: #94a3b8;
+}
+.form-field input:hover {
+  border-color: #64748b;
+}
+.form-field input:focus {
+  outline: 2px solid var(--focus);
+  outline-offset: 2px;
+  border-color: var(--focus);
+}
+.form-field input[aria-invalid="true"] {
+  border-color: var(--error);
+  background: var(--error-bg);
+}
+.form-field input[aria-invalid="true"]:focus {
+  outline-color: var(--error);
+  border-color: var(--error);
+}
+
+.help-text {
+  margin: 0;
+  font-size: 0.8125rem;
+  color: var(--muted);
+}
+.error-message {
+  margin: 0;
+  font-size: 0.8125rem;
+  color: var(--error);
+  font-weight: 500;
+}
+
+/* Submit */
+.submit-button {
+  font: inherit;
+  font-weight: 600;
+  background: var(--accent);
+  color: var(--accent-contrast);
+  border: 1px solid var(--accent);
+  border-radius: 8px;
+  padding: 0.75rem 1.25rem;
+  cursor: pointer;
+  align-self: flex-start;
+  min-height: 44px;
+  transition: background-color 0.15s ease;
+}
+.submit-button:hover {
+  background: var(--accent-hover);
+  border-color: var(--accent-hover);
+}
+.submit-button:focus-visible {
+  outline: 2px solid var(--focus);
+  outline-offset: 2px;
+}
+
+.form-status {
+  margin: 0;
+  font-size: 0.9375rem;
+  color: var(--text);
+  min-height: 1.25rem;
+}
+.form-status.is-success {
+  color: #065f46;
+  font-weight: 500;
+}
+
+/* Responsive */
+@media (max-width: 480px) {
+  .card {
+    padding: 1.5rem 1.25rem;
+  }
+  h1 {
+    font-size: 1.5rem;
+  }
+  .submit-button {
+    align-self: stretch;
+  }
+}
+
+/* Forced colors */
+@media (forced-colors: active) {
+  .form-field input,
+  .submit-button,
+  .card {
+    border: 1px solid CanvasText;
+  }
+  .form-field input[aria-invalid="true"] {
+    outline: 2px solid Mark;
+  }
+  .submit-button {
+    background: ButtonFace;
+    color: ButtonText;
+  }
+}
+
